// tb_l2_slice.sv -- L2 slice testbench: hit/miss/evict/dirty writeback,
// per-op atomics, error cases, golden interleave mapping, and a multi-seed
// random soak against a reference model.
// Expect NG_L2_TB_PASS.
//
// Golden vectors: rtl/gpu/tb/golden/*.hex (generated by
// rtl/gpu/tb/gen_golden/gen_interleave_golden.py).
// Pass the directory with +GOLDEN_DIR=<path> (default rtl/gpu/tb/golden).
`timescale 1ns/1ps
module tb_l2_slice;
  import ng_noc_pkg::*;
  import ng_l2_addrmap::*;

  localparam int SETS = 16, WAYS = 4, LINE_BYTES = 128;
  localparam int AXI_AW = 33, AXI_DW = 512, AXI_IW = 6;

  logic clk = 1'b0;
  logic rst_n;
  always #5 clk = ~clk;

  // ---- DUT + DDR model -----------------------------------------------------
  logic              s_req_valid = 1'b0;
  logic              s_req_ready;
  flit_t             s_req_flit;
  logic              m_resp_valid;
  logic              m_resp_ready = 1'b1;
  flit_t             m_resp_flit;

  logic              arvalid, arready, rvalid, rready, rlast;
  logic [AXI_AW-1:0] araddr;
  logic [7:0]        arlen;
  logic [2:0]        arsize;
  logic [1:0]        arburst;
  logic [AXI_IW-1:0] arid, rid;
  logic [AXI_DW-1:0] rdata;
  logic [1:0]        rresp;
  logic              awvalid, awready, wvalid, wready, wlast, bvalid, bready;
  logic [AXI_AW-1:0] awaddr;
  logic [7:0]        awlen;
  logic [2:0]        awsize;
  logic [1:0]        awburst;
  logic [AXI_IW-1:0] awid, bid;
  logic [AXI_DW-1:0] wdata;
  logic [AXI_DW/8-1:0] wstrb;
  logic [1:0]        bresp;

  ng_l2_slice #(
    .SETS(SETS), .WAYS(WAYS), .LINE_BYTES(LINE_BYTES),
    .AXI_AW(AXI_AW), .AXI_DW(AXI_DW), .AXI_IW(AXI_IW), .SLICE_ID(0)
  ) dut (
    .clk(clk), .rst_n(rst_n),
    .s_req_valid(s_req_valid), .s_req_ready(s_req_ready), .s_req_flit(s_req_flit),
    .m_resp_valid(m_resp_valid), .m_resp_ready(m_resp_ready),
    .m_resp_flit(m_resp_flit),
    .arvalid(arvalid), .arready(arready), .araddr(araddr), .arlen(arlen),
    .arsize(arsize), .arburst(arburst), .arid(arid),
    .rvalid(rvalid), .rready(rready), .rdata(rdata), .rlast(rlast),
    .rid(rid), .rresp(rresp),
    .awvalid(awvalid), .awready(awready), .awaddr(awaddr), .awlen(awlen),
    .awsize(awsize), .awburst(awburst), .awid(awid),
    .wvalid(wvalid), .wready(wready), .wdata(wdata), .wstrb(wstrb),
    .wlast(wlast),
    .bvalid(bvalid), .bready(bready), .bid(bid), .bresp(bresp)
  );

  tb_l2_axi_mem_model #(.AW(AXI_AW), .DW(AXI_DW), .IW(AXI_IW)) u_mem (
    .clk(clk), .rst_n(rst_n),
    .arvalid(arvalid), .arready(arready), .araddr(araddr), .arlen(arlen),
    .arsize(arsize), .arburst(arburst), .arid(arid),
    .rvalid(rvalid), .rready(rready), .rdata(rdata), .rlast(rlast),
    .rid(rid), .rresp(rresp),
    .awvalid(awvalid), .awready(awready), .awaddr(awaddr), .awlen(awlen),
    .awsize(awsize), .awburst(awburst), .awid(awid),
    .wvalid(wvalid), .wready(wready), .wdata(wdata), .wstrb(wstrb),
    .wlast(wlast),
    .bvalid(bvalid), .bready(bready), .bid(bid), .bresp(bresp)
  );

  // capture every DDR read address for the golden mapping check
  logic [AXI_AW-1:0] last_araddr;
  int                ar_cnt;
  always_ff @(posedge clk) begin
    if (!rst_n) ar_cnt <= 0;
    else if (arvalid && arready) begin
      last_araddr <= araddr;
      ar_cnt      <= ar_cnt + 1;
    end
  end

  // ---- golden vectors ------------------------------------------------------
  localparam int GMAX = 2048;
  logic [47:0] g_off   [GMAX];
  logic [47:0] g_choff [GMAX];
  logic [7:0]  g_slice [GMAX];
  logic [7:0]  g_ch    [GMAX];
  logic [31:0] g_cnt_arr [1];
  logic [31:0] g_cnt;
  string        gdir;

  // ---- reference model -----------------------------------------------------
  logic [7:0] refmem [logic [47:0]];
  int errors, checks;

  function automatic logic [7:0] hash48(input logic [47:0] a);
    logic [63:0] p;
    p = a * 64'h9E3779B97F4A7C15;
    return p[55:48];
  endfunction

  function automatic logic [7:0] refbyte(input logic [47:0] pa);
    return refmem.exists(pa) ? refmem[pa] : hash48(l2_ch_of(pa).off);
  endfunction

  function automatic logic [63:0] ref_alu(input logic [4:0] o, input logic w64,
                                          input logic [63:0] av,
                                          input logic [63:0] bv,
                                          input logic [63:0] cv);
    logic [31:0] a32, b32, r32;
    a32 = av[31:0];
    b32 = bv[31:0];
    if (w64) begin
      unique case (o)
        AMO_ADD:   return av + bv;
        AMO_SUB:   return av - bv;
        AMO_AND:   return av & bv;
        AMO_OR:    return av | bv;
        AMO_XOR:   return av ^ bv;
        AMO_MIN_S: return ($signed(av) < $signed(bv)) ? av : bv;
        AMO_MAX_S: return ($signed(av) > $signed(bv)) ? av : bv;
        AMO_MIN_U: return (av < bv) ? av : bv;
        AMO_MAX_U: return (av > bv) ? av : bv;
        AMO_XCHG:  return bv;
        AMO_CAS:   return (av == cv) ? bv : av;
        default:   return av;
      endcase
    end else begin
      unique case (o)
        AMO_ADD:   r32 = a32 + b32;
        AMO_SUB:   r32 = a32 - b32;
        AMO_AND:   r32 = a32 & b32;
        AMO_OR:    r32 = a32 | b32;
        AMO_XOR:   r32 = a32 ^ b32;
        AMO_MIN_S: r32 = ($signed(a32) < $signed(b32)) ? a32 : b32;
        AMO_MAX_S: r32 = ($signed(a32) > $signed(b32)) ? a32 : b32;
        AMO_MIN_U: r32 = (a32 < b32) ? a32 : b32;
        AMO_MAX_U: r32 = (a32 > b32) ? a32 : b32;
        AMO_XCHG:  r32 = b32;
        AMO_CAS:   r32 = (a32 == cv[31:0]) ? b32 : a32;
        AMO_INC:   r32 = (a32 >= b32) ? 32'd0 : a32 + 32'd1;
        AMO_DEC:   r32 = (a32 == 32'd0 || a32 > b32) ? b32 : a32 - 32'd1;
        default:   r32 = a32;
      endcase
      return {32'd0, r32};
    end
  endfunction

  // apply a request to the reference model; returns the expected resp data
  function automatic logic [63:0] ref_apply(input flit_t f);
    logic [63:0] old, newv, nbytes;
    int nb;
    nb = 1 << f.size;
    old = '0;
    for (int b = 0; b < 8; b++)
      if (b < nb) old[8*b +: 8] = refbyte(f.addr + 48'(b));
    if (f.kind == KIND_WR) begin
      for (int b = 0; b < 8; b++)
        if (f.be[b]) refmem[f.addr + 48'(b)] = f.data[8*b +: 8];
      return 64'd0;
    end else if (f.kind == KIND_AMO) begin
      newv = ref_alu(f.op, f.size == SZ_8, old, f.data, f.cmp);
      for (int b = 0; b < 8; b++)
        if (b < nb) refmem[f.addr + 48'(b)] = newv[8*b +: 8];
      return old;
    end else begin
      return old;
    end
  endfunction

  // ---- bus tasks (stimulus at negedge, no posedge races) -------------------
  task automatic send_req(input flit_t f);
    s_req_valid = 1'b1;
    s_req_flit  = f;
    while (!s_req_ready) @(negedge clk);
    @(negedge clk);  // the posedge in between performed the handshake
    s_req_valid = 1'b0;
  endtask

  task automatic recv_resp(output flit_t r);
    m_resp_ready = 1'b1;
    while (!m_resp_valid) @(negedge clk);
    r = m_resp_flit;
    @(negedge clk);
  endtask

  task automatic do_op(input flit_t f, output flit_t r);
    logic [63:0] want;
    want = ref_apply(f);
    send_req(f);
    recv_resp(r);
    checks++;
    if (r.err != ERR_NONE) begin
      errors++;
      $display("TB_FAIL: unexpected err=%0d kind=%0d addr=%h", r.err, f.kind, f.addr);
    end else if ((f.kind == KIND_RD) || (f.kind == KIND_AMO && f.rtn)) begin
      if (r.data !== want) begin
        errors++;
        $display("TB_FAIL: kind=%0d op=%0d addr=%h data=%h want=%h",
                 f.kind, f.op, f.addr, r.data, want);
      end
    end
  endtask

  function automatic flit_t mk_rd(input logic [47:0] pa, input logic [1:0] sz,
                                  input logic [7:0] tag);
    return '{cls: CLS_REQ, kind: KIND_RD, op: AMO_NONE, size: sz, rtn: 1'b0,
             addr: pa, src: 6'd1, dst: 6'd0, tag: tag, be: 8'h00,
             default: '0};
  endfunction

  function automatic flit_t mk_wr(input logic [47:0] pa, input logic [1:0] sz,
                                  input logic [63:0] d, input logic [7:0] be,
                                  input logic [7:0] tag);
    return '{cls: CLS_REQ, kind: KIND_WR, op: AMO_NONE, size: sz, rtn: 1'b0,
             addr: pa, src: 6'd1, dst: 6'd0, tag: tag, data: d, be: be,
             default: '0};
  endfunction

  function automatic flit_t mk_amo(input logic [47:0] pa, input logic [4:0] op,
                                   input logic [1:0] sz, input logic rtn,
                                   input logic [63:0] d, input logic [63:0] cmp,
                                   input logic [7:0] tag);
    return '{cls: CLS_REQ, kind: KIND_AMO, op: op, size: sz, rtn: rtn,
             addr: pa, src: 6'd1, dst: 6'd0, tag: tag, data: d, cmp: cmp,
             default: '0};
  endfunction

  task automatic expect_err(input flit_t f, input logic [1:0] e);
    flit_t r;
    send_req(f);
    recv_resp(r);
    checks++;
    if (r.err != e) begin
      errors++;
      $display("TB_FAIL: err case kind=%0d addr=%h got err=%0d want %0d",
               f.kind, f.addr, r.err, e);
    end
  endtask

  // ---- main ----------------------------------------------------------------
  flit_t f, r;
  initial begin
    errors = 0;
    checks = 0;
    if (!$value$plusargs("GOLDEN_DIR=%s", gdir)) gdir = "golden";

    rst_n = 1'b0;
    repeat (4) @(negedge clk);
    rst_n = 1'b1;
    repeat (2) @(negedge clk);

    // ================= 1) golden interleave mapping =====================
    $readmemh({gdir, "/l2_map_vram_off.hex"}, g_off);
    $readmemh({gdir, "/l2_map_choff.hex"}, g_choff);
    $readmemh({gdir, "/l2_map_slice.hex"}, g_slice);
    $readmemh({gdir, "/l2_map_ch.hex"}, g_ch);
    $readmemh({gdir, "/l2_map_count.hex"}, g_cnt_arr);
    g_cnt = g_cnt_arr[0];
    $display("TB: golden vectors = %0d", g_cnt);

    for (int i = 0; i < int'(g_cnt); i++) begin
      ch_addr_s ca;
      logic [63:0] want;
      // function-level check against the golden definition
      checks++;
      ca = l2_ch_of(g_off[i]);
      if ((ca.ch != 3'(g_ch[i])) || (ca.off != g_choff[i]) ||
          (l2_slice_idx(g_off[i]) != int'(g_slice[i]))) begin
        errors++;
        $display("TB_FAIL: golden fn mismatch off=%h ch=%h.%h want %0h.%0h slice %0d/%0d",
                 g_off[i], ca.ch, ca.off, g_ch[i], g_choff[i],
                 l2_slice_idx(g_off[i]), g_slice[i]);
      end
      // system-level: an in-line 8 B read must hit the golden channel offset
      if (32'(g_off[i][6:0]) + 8 <= 128) begin
        int cnt0;
        cnt0 = ar_cnt;
        do_op(mk_rd(g_off[i], SZ_8, 8'(i)), r);
        for (int b = 0; b < 8; b++)
          want[8*b +: 8] = hash48(g_choff[i] + 48'(b));
        checks++;
        if (r.data !== want) begin
          errors++;
          $display("TB_FAIL: golden data off=%h data=%h want=%h",
                   g_off[i], r.data, want);
        end
        if (ar_cnt > cnt0 &&
            (last_araddr != AXI_AW'(g_choff[i] & ~48'h7F))) begin
          errors++;
          $display("TB_FAIL: golden araddr off=%h choff=%h araddr=%h",
                   g_off[i], g_choff[i], last_araddr);
        end
      end
    end

    // ================= 2) write / read-back / dirty evict ================
    begin
      logic [47:0] pa0;
      pa0 = 48'h0;
      do_op(mk_rd(pa0, SZ_8, 8'hA0), r);              // cold miss fill
      do_op(mk_wr(pa0 + 48'd4, SZ_4, 64'hAABBCCDD, 8'h0F, 8'hA1), r);
      do_op(mk_rd(pa0 + 48'd4, SZ_4, 8'hA2), r);      // hit, written data
      // read 64 distinct lines of set 0 (pa = k * 8192: lineaddr = k*64,
      // set = 0; all land in C1 granules with distinct channel offsets, so
      // they cannot alias pa0's line in the single-channel DDR model) to
      // force eviction of pa0's dirty line
      for (int k = 1; k <= SETS * WAYS; k++)
        do_op(mk_rd(48'(k * 8192), SZ_8, 8'(k)), r);
      // pa0's line was evicted (dirty): read back through a refill
      do_op(mk_rd(pa0 + 48'd4, SZ_4, 8'hA3), r);
      // and the DDR model must now hold the written bytes
      for (int b = 4; b < 8; b++) begin
        ch_addr_s ca;
        ca = l2_ch_of(pa0 + 48'(b));
        checks++;
        if (u_mem.peek(ca.off) !== 8'((64'hAABBCCDD >> (8 * (b - 4))) & 64'hFF)) begin
          errors++;
          $display("TB_FAIL: dirty wb byte pa=%h mem=%h want=%h",
                   pa0 + 48'(b), u_mem.peek(ca.off),
                   8'((64'hAABBCCDD >> (8 * (b - 4))) & 64'hFF));
        end
      end
    end

    // ================= 3) AMO suite ======================================
    begin
      logic [47:0] base;
      logic [4:0] ops [13];
      ops = '{AMO_ADD, AMO_SUB, AMO_AND, AMO_OR, AMO_XOR, AMO_MIN_S,
              AMO_MAX_S, AMO_MIN_U, AMO_MAX_U, AMO_XCHG, AMO_CAS,
              AMO_INC, AMO_DEC};
      base = 48'h0002_0000;
      // one miss + one hit per op, 32-bit, rtn
      for (int i = 0; i < 13; i++) begin
        logic [47:0] pa;
        logic [63:0] d;
        pa = base + 48'(i * 16);
        d  = 64'h0000_0033 + 64'(i);
        do_op(mk_amo(pa, ops[i], SZ_4, 1'b1, d, 64'd0, 8'(i)), r);      // miss+fill
        do_op(mk_amo(pa, ops[i], SZ_4, 1'b1, d + 64'd1, 64'd0, 8'(i)), r); // hit
      end
      // 64-bit at an unaligned offset (miss then hit)
      do_op(mk_amo(base + 48'h1005, AMO_ADD, SZ_8, 1'b1, 64'h1111, 64'd0, 8'h80), r);
      do_op(mk_amo(base + 48'h1005, AMO_ADD, SZ_8, 1'b1, 64'h2222, 64'd0, 8'h81), r);
      // 32-bit unaligned
      do_op(mk_amo(base + 48'h2003, AMO_XCHG, SZ_4, 1'b1, 64'hCAFEBABE, 64'd0, 8'h82), r);
      // CAS: first write a known value, then CAS against it
      do_op(mk_wr(base + 48'h3000, SZ_8, 64'h0102030405060708, 8'hFF, 8'h83), r);
      do_op(mk_amo(base + 48'h3000, AMO_CAS, SZ_8, 1'b1, 64'hDEAD, 64'h0102030405060708,
                   8'h84), r);
      do_op(mk_rd(base + 48'h3000, SZ_8, 8'h85), r);
      do_op(mk_amo(base + 48'h3000, AMO_CAS, SZ_8, 1'b1, 64'hBEEF, 64'h0102, 8'h86), r);
      do_op(mk_rd(base + 48'h3000, SZ_8, 8'h87), r);
      // inc/dec wrap
      do_op(mk_wr(base + 48'h4000, SZ_4, 64'd7, 8'h0F, 8'h88), r);
      do_op(mk_amo(base + 48'h4000, AMO_INC, SZ_4, 1'b1, 64'd7, 64'd0, 8'h89), r);
      do_op(mk_amo(base + 48'h4000, AMO_INC, SZ_4, 1'b1, 64'd7, 64'd0, 8'h8A), r);
      do_op(mk_amo(base + 48'h4000, AMO_DEC, SZ_4, 1'b1, 64'd9, 64'd0, 8'h8B), r);
    end

    // ================= 4) error cases ====================================
    expect_err(mk_rd(48'h0010_0000_0000, SZ_8, 8'hE0), ERR_BAD_PA);   // SYS
    expect_err(mk_wr(48'h8000_0000_0000, SZ_8, 64'd1, 8'hFF, 8'hE1), ERR_BAD_PA);
    expect_err(mk_rd(48'h7F, SZ_8, 8'hE2), ERR_CROSS);                // off 127 + 8
    expect_err(mk_wr(48'h7D, SZ_8, 64'd1, 8'hFF, 8'hE3), ERR_CROSS);
    expect_err(mk_amo(48'h7F, AMO_ADD, SZ_8, 1'b0, 64'd1, 64'd0, 8'hE4), ERR_CROSS);
    expect_err(mk_amo(48'h5000, AMO_ADD, SZ_2, 1'b0, 64'd1, 64'd0, 8'hE5), ERR_BAD_PA);
    expect_err(mk_amo(48'h5000, AMO_INC, SZ_8, 1'b0, 64'd1, 64'd0, 8'hE6), ERR_BAD_PA);

    // ================= 5) random soak, multiple seeds ====================
    // Seeds: 0..3 internally; the whole run is additionally reseedable with
    // xsim -sv_seed (all $urandom calls then derive from it).
    for (int sd = 0; sd < 4; sd++) begin
      rst_n = 1'b0;
      refmem.delete();
      repeat (2) @(negedge clk);
      rst_n = 1'b1;
      repeat (2) @(negedge clk);
      for (int n = 0; n < 256; n++) begin
        logic [47:0] pa;
        logic [1:0] sz;
        logic [63:0] d;
        logic [7:0] be;
        logic [4:0] o;
        pa  = 48'h0001_0000 + 48'($urandom % 8192);
        if (pa[6:0] > 48'd120) pa = pa & ~48'h7F;  // keep 8 B accesses in-line
        sz  = SZ_8;
        d   = 64'($urandom);
        case ($urandom_range(0, 9))
          0, 1, 2, 3: do_op(mk_rd(pa, SZ_8, 8'(n & 8'hFF)), r);
          4, 5, 6: begin
            be = ($urandom_range(0, 3) == 0) ? 8'h0F : 8'hFF;
            do_op(mk_wr(pa, sz, d, be, 8'(n & 8'hFF)), r);
          end
          default: begin
            o = 5'($urandom_range(0, 12));
            sz = ((o == AMO_INC) || (o == AMO_DEC)) ? SZ_4 :
                 (($urandom_range(0, 1) == 0) ? SZ_4 : SZ_8);
            do_op(mk_amo(pa, o, sz, 1'b1, d, 64'($urandom), 8'(n & 8'hFF)), r);
          end
        endcase
        if ($urandom_range(0, 3) == 0) repeat ($urandom_range(0, 3)) @(negedge clk);
      end
      $display("TB: soak round %0d done (%0d checks so far)", sd, checks);
    end

    if (errors == 0)
      $display("NG_L2_TB_PASS: %0d checks, 0 errors", checks);
    else
      $display("NG_L2_TB_FAIL: %0d errors of %0d checks", errors, checks);
    $finish;
  end

  // watchdog
  initial begin
    #10_000_000;
    $display("NG_L2_TB_FAIL: watchdog timeout");
    $finish;
  end
endmodule
